<?php
declare(strict_types=1);namespace QualitySystem\Services;use PDO;use RuntimeException;use QualitySystem\Repositories\ProgramManualRepository;use QualitySystem\Security\AuditLogger;use QualitySystem\Security\PermissionMatrix;
final class ProgramManualAutomationService{public function __construct(private PDO$pdo,private ProgramManualRepository$repo){}
 public function run(int$id,string$role,int$user):array{if(!PermissionMatrix::allows($role,'program_manuals','update'))throw new RuntimeException('Forbidden',403);$m=$this->repo->find($id,$role,$user);if(!$m)throw new RuntimeException('Program manual not found.',404);$program=(int)$m['program_specification_id'];$this->pdo->beginTransaction();try{$this->mapRows($id,'Course','program_manual_courses','course_code','course_name','program_specification_courses','course_code','course_title','program_specification_id',$program);$this->mapRows($id,'PLO','program_manual_plos','plo_code','description','program_specification_plos','plo_code','plo_text','program_specification_id',$program);$this->mapEntities($id,'Staff','program_staff','email','full_name');$this->mapEntities($id,'Committee','committees','committee_name','committee_name');$missing=(int)$this->pdo->query("SELECT COUNT(*) FROM program_manual_mappings WHERE program_manual_id=$id AND status='Missing'")->fetchColumn();if($missing){$this->pdo->prepare("INSERT IGNORE INTO tasks(task_title,task_description,related_module,related_record_id,program_specification_id,created_by_user_id,due_date,priority,status) VALUES(:title,:description,'Program Manuals',:manual,:program,:user,DATE_ADD(CURDATE(),INTERVAL 30 DAY),'High','Pending')")->execute([':title'=>'Resolve unmatched records for program manual '.$id,':description'=>"Review $missing unmatched course, PLO, staff, or committee records.",':manual'=>$id,':program'=>$program,':user'=>$user]);}$this->refreshNotifications($id,$m,$missing);AuditLogger::record($this->pdo,'program_manual_automation','allowed','Program Manuals',[],'program_manual',$id);$this->pdo->commit();return$this->summary($id);}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 private function mapRows(int$id,string$type,string$source,string$key,string$label,string$target,string$tkey,string$tlabel,string$scope,int$program):void{$rows=$this->pdo->prepare("SELECT id,$key source_key,$label source_label FROM $source WHERE program_manual_id=:id");$rows->execute([':id'=>$id]);$find=$this->pdo->prepare("SELECT id,$tkey target_key,$tlabel target_label FROM $target WHERE $scope=:program");$find->execute([':program'=>$program]);$targets=$find->fetchAll(PDO::FETCH_ASSOC);foreach($rows->fetchAll(PDO::FETCH_ASSOC)as$r){[$targetId,$method,$confidence]=$this->best($r,$targets);$this->upsert($id,$type,(int)$r['id'],$targetId,$method,$confidence);}}
 private function mapEntities(int$id,string$type,string$table,string$key,string$label):void{$rows=$this->pdo->prepare('SELECT id,source_key,source_label FROM program_manual_entities WHERE program_manual_id=:id AND entity_type=:type');$rows->execute([':id'=>$id,':type'=>$type]);$targets=$this->pdo->query("SELECT id,$key target_key,$label target_label FROM $table")->fetchAll(PDO::FETCH_ASSOC);foreach($rows->fetchAll(PDO::FETCH_ASSOC)as$r){[$targetId,$method,$confidence]=$this->best($r,$targets);$this->upsert($id,$type,(int)$r['id'],$targetId,$method,$confidence);}}
 private function best(array$r,array$targets):array{$key=$this->norm((string)$r['source_key']);$label=$this->norm((string)$r['source_label']);$best=[null,'none',0.0];foreach($targets as$t){$tk=$this->norm((string)($t['target_key']??''));$tl=$this->norm((string)($t['target_label']??''));if($key!==''&&$key===$tk)return[(int)$t['id'],'exact_key',100.0];similar_text($label,$tl,$pct);if($pct>$best[2])$best=[(int)$t['id'],'fuzzy_label',round($pct,2)];}return$best[2]>=75?$best:[null,'none',0.0];}
 private function upsert(int$id,string$type,int$source,?int$target,string$method,float$confidence):void{$status=$target===null?'Missing':'Suggested';$sql="INSERT INTO program_manual_mappings(program_manual_id,source_type,source_record_id,target_record_id,match_method,confidence,status) VALUES(:id,:type,:source,:target,:method,:confidence,:status) ON DUPLICATE KEY UPDATE target_record_id=IF(status IN('Confirmed','Rejected'),target_record_id,VALUES(target_record_id)),match_method=IF(status IN('Confirmed','Rejected'),match_method,VALUES(match_method)),confidence=IF(status IN('Confirmed','Rejected'),confidence,VALUES(confidence)),status=IF(status IN('Confirmed','Rejected'),status,VALUES(status))";$this->pdo->prepare($sql)->execute(compact('id','type','source','target','method','confidence','status'));}
 private function refreshNotifications(int$id,array$m,int$missing):void{if($missing)$this->notify($id,'unmatched',"$missing manual records require matching",date('Y-m-d',strtotime('+30 days')));if(!empty($m['next_review_date'])&&$m['next_review_date']<=date('Y-m-d',strtotime('+90 days')))$this->notify($id,'review_due','Program manual review is due on '.$m['next_review_date'],$m['next_review_date']);if($m['reconciliation_status']==='Pending Approval')$this->notify($id,'approval','Reconciliation is awaiting independent approval',null);}
 private function notify(int$id,string$type,string$message,?string$due):void{$this->pdo->prepare('INSERT IGNORE INTO program_manual_notifications(program_manual_id,notification_type,message,due_date) VALUES(:id,:type,:message,:due)')->execute(compact('id','type','message','due'));}
 public function summary(int$id):array{$s=$this->pdo->prepare('SELECT source_type,status,COUNT(*) count FROM program_manual_mappings WHERE program_manual_id=:id GROUP BY source_type,status ORDER BY source_type,status');$s->execute([':id'=>$id]);$n=$this->pdo->prepare("SELECT * FROM program_manual_notifications WHERE program_manual_id=:id AND status='Open' ORDER BY due_date IS NULL,due_date");$n->execute([':id'=>$id]);return['mappings'=>$s->fetchAll(PDO::FETCH_ASSOC),'notifications'=>$n->fetchAll(PDO::FETCH_ASSOC)];}
 private function norm(string$v):string{return preg_replace('/[^a-z0-9]+/','',strtolower($v))??'';}}
